CREATE TABLE IF NOT EXISTS gis_phase39116_lineage_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL, algorithm_version text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, lineage_hit_count integer NOT NULL DEFAULT 0, authoritative_geometry_hit_count integer NOT NULL DEFAULT 0, eligible_resolution_count integer NOT NULL DEFAULT 0, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);